export interface ConnectorConfig {
  /** GitHub repository owner (user or organization) */
  githubOwner: string
  /** GitHub repository name */
  githubRepo: string
  /** GitHub personal access token with repo write scope (from GITHUB_TOKEN env var) */
  githubToken: string
  /** Zendesk subdomain (e.g., 'mycompany' for mycompany.zendesk.com) */
  zendeskSubdomain: string
  /** Zendesk API token with ticket:write scope (from ZENDESK_TOKEN env var) */
  zendeskToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  detail: {
    id: string
    subject: string
    description: string
    [key: string]: unknown
  }
  [key: string]: unknown
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

async function doFetch(
  fetchFn: typeof fetch,
  url: string,
  options: RequestInit,
): Promise<Response> {
  const response = await fetchFn(url, options)
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} ${response.statusText} from ${url}`)
  }
  return response
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  // Validate required fields
  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id (Zendesk ticket ID)')
  }
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject (Zendesk ticket subject)')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description (Zendesk ticket description)')
  }

  const ticketId = payload.detail.id
  const subject = payload.detail.subject
  const description = payload.detail.description

  // Step 1: Create GitHub issue
  const githubUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubResponse = await doFetch(fetchFn, githubUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2026-03-10',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      title: subject,
      body: description,
    }),
  })
  const githubIssue = (await githubResponse.json()) as {
    number: number
    html_url: string
  }

  // Step 2: Post comment on Zendesk ticket with GitHub issue URL
  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`
  const zendeskResponse = await doFetch(fetchFn, zendeskUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      comment: {
        body: `GitHub issue created: ${githubIssue.html_url}`,
      },
    }),
  })
  const zendeskComment = (await zendeskResponse.json()) as {
    comment: {
      id: number
    }
  }

  return {
    githubIssueNumber: githubIssue.number,
    githubIssueUrl: githubIssue.html_url,
    zendeskCommentId: zendeskComment.comment.id,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubOwner: 'test-owner',
      githubRepo: 'test-repo',
      githubToken: 'gh-token',
      zendeskSubdomain: 'test-subdomain',
      zendeskToken: 'zd-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueNumber).toBe(14038)
    expect(result.githubIssueUrl).toBe('https://github.com/test-owner/test-repo/issues/14038')
    expect(result.zendeskCommentId).toBe(12345)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      githubOwner: 'test-owner',
      githubRepo: 'test-repo',
      githubToken: 'gh-token',
      zendeskSubdomain: 'test-subdomain',
      zendeskToken: 'zd-token',
      fetch: undefined as unknown as typeof fetch,
    }
    calls = []
  })

  function makeFetch(handler: (req: RecordedCall) => Response | Promise<Response>) {
    const { fetch, calls: recordedCalls } = fakeFetch(handler)
    baseConfig.fetch = fetch
    calls.push(...recordedCalls)
    return recordedCalls
  }

  it('creates GitHub issue and posts Zendesk comment on happy path', async () => {
    const recordedCalls = makeFetch((req) => {
      if (req.url.includes('/repos/test-owner/test-repo/issues')) {
        expect(req.method).toBe('POST')
        expect(req.json).toEqual({ title: 'Test Subject', body: 'Test Description' })
        expect(req.headers.get('authorization')).toBe('Bearer gh-token')
        expect(req.headers.get('accept')).toBe('application/vnd.github+json')
        expect(req.headers.get('x-github-api-version')).toBe('2026-03-10')
        return jsonResponse({ number: 42, html_url: 'https://github.com/test-owner/test-repo/issues/42' }, 201)
      }
      if (req.url.includes('/tickets/123/comments.json')) {
        expect(req.method).toBe('POST')
        expect(req.json).toEqual({
          comment: { body: 'GitHub issue created: https://github.com/test-owner/test-repo/issues/42' },
        })
        expect(req.headers.get('authorization')).toBe('Bearer zd-token')
        return jsonResponse({ comment: { id: 999 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '123', subject: 'Test Subject', description: 'Test Description' },
    }
    const result = await handle(payload, baseConfig)

    expect(result.githubIssueNumber).toBe(42)
    expect(result.githubIssueUrl).toBe('https://github.com/test-owner/test-repo/issues/42')
    expect(result.zendeskCommentId).toBe(999)
    expect(recordedCalls.length).toBe(2)
  })

  it('sends correct Authorization headers for both APIs', async () => {
    makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        expect(req.headers.get('authorization')).toBe('Bearer gh-token')
        return jsonResponse({ number: 1, html_url: 'https://github.com/o/r/issues/1' }, 201)
      }
      if (req.url.includes('/comments.json')) {
        expect(req.headers.get('authorization')).toBe('Bearer zd-token')
        return jsonResponse({ comment: { id: 1 } }, 201)
      }
      return jsonResponse({}, 404)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '1', subject: 'S', description: 'D' },
    }
    await handle(payload, baseConfig)
  })

  it('maps subject to title and description to body', async () => {
    let githubBody: unknown
    makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        githubBody = req.json
        return jsonResponse({ number: 1, html_url: 'https://github.com/o/r/issues/1' }, 201)
      }
      return jsonResponse({ comment: { id: 1 } }, 201)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '1', subject: 'My Title', description: 'My Body' },
    }
    await handle(payload, baseConfig)

    expect(githubBody).toEqual({ title: 'My Title', body: 'My Body' })
  })

  it('throws descriptive error when detail.id is missing', async () => {
    makeFetch(() => jsonResponse({}, 200))

    const payload = { detail: { subject: 'S', description: 'D' } } as ZendeskTicketCreatedPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: detail.id')
  })

  it('throws descriptive error when detail.subject is missing', async () => {
    makeFetch(() => jsonResponse({}, 200))

    const payload = { detail: { id: '1', description: 'D' } } as ZendeskTicketCreatedPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: detail.subject')
  })

  it('throws descriptive error when detail.description is missing', async () => {
    makeFetch(() => jsonResponse({}, 200))

    const payload = { detail: { id: '1', subject: 'S' } } as ZendeskTicketCreatedPayload
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: detail.description')
  })

  it('throws with status and endpoint on non-2xx GitHub response', async () => {
    makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        return jsonResponse({ message: 'Bad credentials' }, 401)
      }
      return jsonResponse({}, 404)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '1', subject: 'S', description: 'D' },
    }
    await expect(handle(payload, baseConfig)).rejects.toThrow('HTTP 401 Unauthorized from https://api.github.com/repos/test-owner/test-repo/issues')
  })

  it('throws with status and endpoint on non-2xx Zendesk response', async () => {
    makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        return jsonResponse({ number: 1, html_url: 'https://github.com/o/r/issues/1' }, 201)
      }
      if (req.url.includes('/comments.json')) {
        return jsonResponse({ error: 'Forbidden' }, 403)
      }
      return jsonResponse({}, 404)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '1', subject: 'S', description: 'D' },
    }
    await expect(handle(payload, baseConfig)).rejects.toThrow(
      'HTTP 403 Forbidden from https://test-subdomain.zendesk.com/api/v2/tickets/1/comments.json',
    )
  })
})

