  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

async function doFetch(
  fetchFn: typeof fetch,
  url: string,
  options: RequestInit,
): Promise<Response> {
  const response = await fetchFn(url, options)
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} ${response.statusText} from ${url}`)
  }
  return response
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  // Validate required fields
  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id (Zendesk ticket ID)')
  }
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject (Zendesk ticket subject)')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description (Zendesk ticket description)')
  }

  const ticketId = payload.detail.id
  const subject = payload.detail.subject
  const description = payload.detail.description

  // Step 1: Create GitHub issue
  const githubUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubResponse = await doFetch(fetchFn, githubUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2026-03-10',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      title: subject,
      body: description,
    }),
  })
  const githubIssue = (await githubResponse.json()) as {
    number: number
    html_url: string
  }

  // Construct GitHub issue URL from config and issue number (more reliable than API response)
  const githubIssueUrl = `https://github.com/${config.githubOwner}/${config.githubRepo}/issues/${githubIssue.number}`

  // Step 2: Post comment on Zendesk ticket with GitHub issue URL
  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`
  const zendeskResponse = await doFetch(fetchFn, zendeskUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      comment: {
        body: `GitHub issue created: ${githubIssueUrl}`,
      },
    }),
  })
  const zendeskComment = (await zendeskResponse.json()) as {
    comment: {
      id: number
    }
  }

  return {
    githubIssueNumber: githubIssue.number,
    githubIssueUrl,
    zendeskCommentId: zendeskComment.comment.id,
  }
}

